ry_snapshot(actor,p_request)is distinct from snap then perform private.hmac_model_fail(''P0001'');end if;\n return private.company_registry_job_projection(p_request);\nexception when others or query_canceled or assert_failure then perform private.hmac_model_fail(sqlstate);return null;end","name":"request_company_registry_check","metadata":{"acl":["connect_hmac_registration=X/connect_hmac_registration","authenticated=X/connect_hmac_registration"],"args":"2950 2950","owner":"17960","config":["search_path=\"\""],"result":"3802","argnames":["p_request","p_operation"],"parallel":"u","volatile":"v","leakproof":false,"securityDefiner":true},"srcSha256":null},{"oid":"18612","src":null,"name":"company_registry_claim_dto","metadata":{"acl":["connect_hmac_registration=X/connect_hmac_registration"],"args":"2950","owner":"17960","config":["search_path=\"\""],"result":"3802","argnames":["p_job"],"parallel":"u","volatile":"v","leakproof":false,"securityDefiner":false},"srcSha256":"ef2eedd64503ac6bd213459ed2b2b945551741d8cae30a353d570b1924ecd228"},{"oid":"18613","src":"\ndeclare candidate private.company_registry_jobs;j private.company_registry_jobs;cfg private.company_registry_sources;r private.company_registrations;\nbegin\n perform pg_advisory_xact_lock_shared(78104,0);\n if p_lease is null or p_source<>''minhareceita-cnpj-v1''then perform private.hmac_model_fail(''P0001'');end if;\n select*into cfg from private.company_registry_sources z where z.source=p_source and z.policy_version=''company-legal-name-v2''and z.enabled for share;\n if not found then return null;end if;\n select*into j from private.company_registry_jobs z where z.lease_id=p_lease;\n if found then\n  if j.source<>p_source or j.policy_version<>''company-legal-name-v2''then perform private.hmac_model_fail(''P0001'');end if;\n  if j.state=''checking''and j.lease_expires_at>clock_timestamp()and private.company_registry_job_session(j.subject,j.requester_session,j.requester_expires)\n   and private.company_registry_sn