do $$begin if to_regclass('private.company_registry_execution_windows')is not null or exists(select 1 from pg_proc where pronamespace='private'::regnamespace and proname in('registry_execution_immutable','registry_execution_policy_hash','registry_execution_live','registry_execution_state','open_registry_execution_window','claim_registry_execution_window','registry_execution_allows','close_registry_execution_window','registry_execution_temporal_live','fence_registry_execution_window','registry_execution_validate_commit','registry_execution_for_request','registry_execution_result_allowed','registry_execution_proof_allowed'))then raise exception 'Expiring window already installed';end if;end$$;
grant connect_hmac_registration to postgres with inherit false,set true;set local role connect_hmac_registration;
do $$begin if not(not exists(select 1 from private.company_registry_sources where enabled)and not exists(select 1 from private.company_registry_worker_pilots where enabled))then raise exception 'Expiring window requires closed source/pilots';end if;end$$;
-- LOCAL OWNER-ONLY CANDIDATE. No GRANT, global source enable, scheduler, Edge or provider.
-- Effective permission is derived from the database clock; rows remain as audit.

do $$begin if current_user<>'connect_hmac_registration' or to_regprocedure('private.company_registry_job_session(uuid,uuid,timestamp with time zone)')is null or to_regprocedure('private.company_registry_snapshot(uuid,uuid)')is null then raise exception 'Window prerequisites differ';end if;end$$;
create table private.company_registry_execution_windows(
 operation_id uuid primary key,subject uuid not null,request_id uuid not null,session_id uuid not null,company_id uuid not null,
 cnpj text not null,request_snapshot bytea not null,source text not null check(source='minhareceita-cnpj-v1'),
 policy_version text not null check(policy_version='company-legal-name-v2'),source_policy_hash bytea not null,
 starts_at timestamptz not null,expires_at timestamptz not null,token_expires_at timestamptz not null,
 claimed_at timestamptz,closed_at timestamptz,
 check(expires_at>starts_at and expires_at<=starts_at+interval'10minutes' and expires_at<=token_expires_at));
alter table private.company_registry_execution_windows enable row level security;
revoke all on private.company_registry_execution_windows from public,anon,authenticated,service_role;
create table private.company_registry_execution_audit(
 event_id bigint generated always as identity primary key,operation_id uuid not null references private.company_registry_execution_windows,
 kind text not null check(kind in('opened','claimed','closed','commit-fence')),happened_at timestamptz not null default clock_timestamp());
alter table private.company_registry_execution_audit enable row level security;
revoke all on private.company_registry_execution_audit from public,anon,authenticated,service_role;

create function private.registry_execution_immutable()returns trigger language plpgsql security definer set search_path=''as $$begin if TG_OP='DELETE'or TG_TABLE_NAME='company_registry_execution_audit'then raise exception 'Immutable execution window audit';end if;if (to_jsonb(NEW)-array['claimed_at','closed_at'])is distinct from(to_jsonb(OLD)-array['claimed_at','closed_at'])or(OLD.claimed_at is not null and NEW.claimed_at is distinct from OLD.claimed_at)or(OLD.closed_at is not null and NEW.closed_at is distinct from OLD.closed_at)or(NEW.claimed_at is not null and(NEW.claimed_at<NEW.starts_at or NEW.claimed_at>=NEW.expires_at))or(OLD.claimed_at is null and NEW.claimed_at is not null and clock_timestamp()>=NEW.expires_at)then raise exception 'Immutable execution window scope';end if;return NEW;end$$;
create trigger registry_execution_window_immutable before update or delete on private.company_registry_execution_windows for each row execute function private.registry_execution_immutable();
create trigger registry_execution_audit_immutable before update or delete on private.company_registry_execution_audit for each row execute function private.registry_execution_immutable();

create function private.registry_execution_policy_hash()returns bytea language sql security definer set search_path=''as $$
 select sha256(convert_to(jsonb_build_object('source',s.source,'policy',s.policy_version,'max_age',s.max_age_seconds,'dataset_days',s.max_dataset_age_days,'synthetic',s.synthetic_only)::text,'UTF8'))
 from private.company_registry_sources s where s.source='minhareceita-cnpj-v1'and s.policy_version='company-legal-name-v2'
 and not s.enabled and not s.synthetic_only and s.max_age_seconds=600 and s.max_dataset_age_days=45
$$;
create function private.registry_execution_live(p_operation uuid,p_subject uuid,p_session uuid,p_request uuid,p_claimed boolean)returns boolean
 language plpgsql security definer set search_path=''as $$
 declare w private.company_registry_execution_windows;r private.company_registrations;t timestamptz:=clock_timestamp();
 begin
 select*into w from private.company_registry_execution_windows where operation_id=p_operation and subject=p_subject and session_id=p_session and request_id=p_request;
 if not found or w.closed_at is not null or t<w.starts_at or t>=w.expires_at or t>=w.token_expires_at or(p_claimed and w.claimed_at is null)
 or not private.company_registry_job_session(w.subject,w.session_id,w.token_expires_at)
 or w.source_policy_hash is distinct from private.registry_execution_policy_hash()then return false;end if;
 select*into r from private.company_registrations where requester_id=w.subject and request_id=w.request_id;
 if not found or r.state is distinct from'pending'or r.company_id is distinct from w.company_id or r.cnpj is distinct from w.cnpj
 or private.company_registry_snapshot(w.subject,w.request_id)is distinct from w.request_snapshot then return false;end if;
 return exists(select 1 from private.company_controls c where c.company_id=w.company_id and c.state='pending'and c.cnpj is null and c.representation_state='unconfirmed')
 and not exists(select 1 from private.company_controls c where c.cnpj=w.cnpj and c.company_id<>w.company_id);
 end$$;

create function private.registry_execution_state(p_operation uuid)returns jsonb language sql security definer set search_path=''as $$
 select jsonb_build_object('operation_id',w.operation_id,'starts_at',w.starts_at,'expires_at',w.expires_at,
 'state',case when w.closed_at is not null and w.closed_at<w.expires_at then'closed'when clock_timestamp()>=w.expires_at then'expired'
 when not private.registry_execution_live(w.operation_id,w.subject,w.session_id,w.request_id,false)then'invalidated'
 when w.claimed_at is not null then'claimed'else'open'end)
 from private.company_registry_execution_windows w where operation_id=p_operation
$$;
create function private.open_registry_execution_window(p_operation uuid,p_subject uuid,p_session uuid,p_request uuid,p_token_expires timestamptz,p_ttl_ms integer)returns jsonb
 language plpgsql security definer set search_path=''as $$
 declare r private.company_registrations;w private.company_registry_execution_windows;t timestamptz:=clock_timestamp();h bytea;
 begin
 if p_operation is null or p_subject is null or p_session is null or p_request is null or p_token_expires is null
 or p_ttl_ms is null or p_ttl_ms<1 or p_ttl_ms>600000 or p_token_expires<=t
 or not private.company_registry_job_session(p_subject,p_session,p_token_expires)then return null;end if;
 select*into r from private.company_registrations where requester_id=p_subject and request_id=p_request for update;
 if not found or r.state is distinct from'pending'or r.cnpj!~'^[0-9A-Z]{14}$'or private.company_registry_snapshot(p_subject,p_request)is null then return null;end if;
 select*into w from private.company_registry_execution_windows where operation_id=p_operation;
 if found then
 if w.subject<>p_subject or w.session_id<>p_session or w.request_id<>p_request then return null;end if;
 return private.registry_execution_state(p_operation); -- original deadline, never renew.
 end if;
 if exists(select 1 from private.company_registry_execution_windows where subject=p_subject and request_id=p_request and(claimed_at is not null or(closed_at is null and expires_at>t)))
 or exists(select 1 from private.company_registry_jobs where subject=p_subject and request_id=p_request and attempts>0)
 or not exists(select 1 from private.company_controls c where c.company_id=r.company_id and c.state='pending'and c.cnpj is null and c.representation_state='unconfirmed')
 or exists(select 1 from private.company_controls c where c.cnpj=r.cnpj and c.company_id<>r.company_id)then return null;end if;
 h:=private.registry_execution_policy_hash();if h is null then return null;end if;
 insert into private.company_registry_execution_windows(operation_id,subject,request_id,session_id,company_id,cnpj,request_snapshot,source,policy_version,source_policy_hash,starts_at,expires_at,token_expires_at)
 values(p_operation,p_subject,p_request,p_session,r.company_id,r.cnpj,private.company_registry_snapshot(p_subject,p_request),
 'minhareceita-cnpj-v1','company-legal-name-v2',h,t,least(t+p_ttl_ms*interval'1millisecond',p_token_expires),p_token_expires);
 insert into private.company_registry_execution_audit(operation_id,kind)values(p_operation,'opened');
 return private.registry_execution_state(p_operation);
 end$$;

create function private.claim_registry_execution_window(p_operation uuid,p_subject uuid,p_session uuid,p_request uuid)returns jsonb
 language plpgsql security definer set search_path=''as $$
 declare w private.company_registry_execution_windows;
 begin
 select*into w from private.company_registry_execution_windows where operation_id=p_operation for update;
 if not found or w.claimed_at is not null or not private.registry_execution_live(p_operation,p_subject,p_session,p_request,false)then return null;end if;
 begin
 update private.company_registry_execution_windows set claimed_at=clock_timestamp()where operation_id=p_operation;
 insert into private.company_registry_execution_audit(operation_id,kind)values(p_operation,'claimed');
 if not private.registry_execution_live(p_operation,p_subject,p_session,p_request,true)then raise exception using errcode='P0001',message='Window expired';end if;
 return jsonb_build_object('operation_id',p_operation,'subject',w.subject,'session_id',w.session_id,'request_id',w.request_id,'company_id',w.company_id,'cnpj',w.cnpj,'expires_at',w.expires_at);
 exception when sqlstate'P0001'then return null;end;
 end$$;
create function private.registry_execution_allows(p_operation uuid,p_subject uuid,p_session uuid,p_request uuid)returns boolean
 language sql security definer set search_path=''as $$select private.registry_execution_live(p_operation,p_subject,p_session,p_request,true)$$;
create function private.close_registry_execution_window(p_operation uuid,p_subject uuid,p_session uuid)returns jsonb
 language plpgsql security definer set search_path=''as $$
 declare w private.company_registry_execution_windows;
 begin
 select*into w from private.company_registry_execution_windows where operation_id=p_operation and subject=p_subject and session_id=p_session for update;
 if not found then return null;end if;
 if w.closed_at is null then update private.company_registry_execution_windows set closed_at=clock_timestamp()where operation_id=p_operation;
 insert into private.company_registry_execution_audit(operation_id,kind)values(p_operation,'closed');end if;
 return private.registry_execution_state(p_operation);
 end$$;
create function private.registry_execution_temporal_live(p_operation uuid,p_subject uuid,p_session uuid,p_request uuid)returns boolean language sql security definer set search_path=''as $$
 select current_setting('transaction_isolation')='read committed'and exists(
 select 1 from private.company_registry_execution_windows w where w.operation_id=p_operation and w.subject=p_subject and w.session_id=p_session and w.request_id=p_request
 and w.closed_at is null and w.claimed_at is not null and clock_timestamp()>=w.starts_at and clock_timestamp()<w.expires_at
 and clock_timestamp()<w.token_expires_at and private.company_registry_job_session(w.subject,w.session_id,w.token_expires_at)
 and w.source_policy_hash=private.registry_execution_policy_hash())
$$;
create function private.fence_registry_execution_window(p_operation uuid,p_subject uuid,p_session uuid,p_request uuid)returns boolean language plpgsql security definer set search_path=''as $$
 begin if current_setting('transaction_isolation')<>'read committed'or not private.registry_execution_live(p_operation,p_subject,p_session,p_request,true)then return false;end if;
 insert into private.company_registry_execution_audit(operation_id,kind)values(p_operation,'commit-fence');return true;end$$;
create function private.registry_execution_validate_commit()returns trigger language plpgsql security definer set search_path=''as $$
 declare w private.company_registry_execution_windows;
 begin if NEW.kind in('claimed','commit-fence')then
 select*into w from private.company_registry_execution_windows where operation_id=NEW.operation_id;
 if not found or not private.registry_execution_temporal_live(w.operation_id,w.subject,w.session_id,w.request_id)then
 raise exception using errcode='23514',message='Window expired or invalid at commit';end if;end if;return NEW;end$$;
create constraint trigger registry_execution_commit_guard after insert on private.company_registry_execution_audit deferrable initially deferred for each row execute function private.registry_execution_validate_commit();
revoke execute on function private.registry_execution_temporal_live(uuid,uuid,uuid,uuid),private.fence_registry_execution_window(uuid,uuid,uuid,uuid),private.registry_execution_validate_commit()from public,anon,authenticated,service_role;

create view private.company_registry_execution_audit_effective with(security_invoker=true)as
 select operation_id,kind,happened_at,'stored'::text as evidence from private.company_registry_execution_audit
 union all select operation_id,'expired-effective',expires_at,'derived-from-immutable-deadline'
 from private.company_registry_execution_windows where clock_timestamp()>=expires_at and(closed_at is null or closed_at>=expires_at);
revoke all on private.company_registry_execution_audit_effective from public,anon,authenticated,service_role;
revoke execute on function private.registry_execution_immutable(),private.registry_execution_policy_hash(),private.registry_execution_live(uuid,uuid,uuid,uuid,boolean),
 private.registry_execution_state(uuid),private.open_registry_execution_window(uuid,uuid,uuid,uuid,timestamptz,integer),
 private.claim_registry_execution_window(uuid,uuid,uuid,uuid),private.registry_execution_allows(uuid,uuid,uuid,uuid),
 private.close_registry_execution_window(uuid,uuid,uuid)from public,anon,authenticated,service_role;


-- Owner-only integration helpers. No source flag or operational GRANT.
create function private.registry_execution_for_request(p_subject uuid,p_session uuid,p_request uuid)returns uuid language sql security definer set search_path=''as $$
 select operation_id from private.company_registry_execution_windows w where w.subject=p_subject and w.session_id=p_session and w.request_id=p_request and private.registry_execution_live(w.operation_id,w.subject,w.session_id,w.request_id,true)order by starts_at desc limit 1
$$;
create function private.registry_execution_result_allowed(p_op uuid,p_subject uuid,p_session uuid,p_request uuid,p_observed timestamptz,p_expires timestamptz,p_dataset date)returns boolean language sql security definer set search_path=''as $$
 select coalesce(isfinite(p_observed)and isfinite(p_expires)and isfinite(p_dataset)and p_observed<=clock_timestamp()and p_expires>clock_timestamp()
 and extract(day from p_dataset)=1 and p_dataset<=((clock_timestamp()at time zone'UTC')::date)
 and exists(select 1 from private.company_registry_execution_windows w join private.company_registry_sources s on(s.source,s.policy_version)=(w.source,w.policy_version)
 join private.company_registrations r on r.requester_id=w.subject and r.request_id=w.request_id
 where w.operation_id=p_op and w.subject=p_subject and w.session_id=p_session and w.request_id=p_request
 and r.company_id=w.company_id and r.cnpj=w.cnpj and private.company_registry_snapshot(w.subject,w.request_id)=w.request_snapshot
 and private.registry_execution_temporal_live(w.operation_id,w.subject,w.session_id,w.request_id)
 and p_expires<=w.expires_at and p_expires<=p_observed+make_interval(secs=>s.max_age_seconds)
 and clock_timestamp()<((p_dataset+s.max_dataset_age_days)::timestamp at time zone'UTC')
 and p_expires<=((p_dataset+s.max_dataset_age_days)::timestamp at time zone'UTC')),false)
$$;
create function private.registry_execution_proof_allowed(p private.company_registry_proofs,p_session uuid)returns boolean language sql security definer set search_path=''as $$
 select coalesce(exists(select 1 from private.company_registry_jobs j join private.company_registry_job_requests o on o.job_id=j.job_id and o.operation_id=j.lease_id
 join private.company_registry_execution_windows w on w.operation_id=o.operation_id
 where j.proof_id=p.proof_id and j.subject=p.subject and j.request_id=p.request_id and j.company_id=p.company_id and j.request_snapshot=p.request_snapshot
 and j.requester_session=p_session and j.source=p.source and j.policy_version=p.policy_version and o.subject=j.subject and o.requester_session=p_session
 and o.request_snapshot=j.request_snapshot and w.cnpj=p.cnpj and w.request_snapshot=p.request_snapshot
 and private.registry_execution_result_allowed(w.operation_id,j.subject,p_session,j.request_id,p.observed_at,p.expires_at,p.dataset_date)),false)
$$;
revoke all on function private.registry_execution_for_request(uuid,uuid,uuid),private.registry_execution_result_allowed(uuid,uuid,uuid,uuid,timestamptz,timestamptz,date),private.registry_execution_proof_allowed(private.company_registry_proofs,uuid)from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION private.request_company_registry_check(p_request uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;sid uuid;expiry timestamptz;r private.company_registrations;cfg private.company_registry_sources;j private.company_registry_jobs;o private.company_registry_job_requests;snap bytea;new_job uuid;
begin
 perform pg_advisory_xact_lock_shared(78104,0);actor:=private.company_registry_job_actor();sid:=(private.company_registry_request_context()->>'session_id')::uuid;expiry:=to_timestamp((private.company_registry_request_context()->>'exp')::double precision);
 if p_request is null or p_operation is null then perform private.hmac_model_fail('P0001');end if;
 if not private.registry_execution_live(p_operation,actor,sid,p_request,false)then perform private.hmac_model_fail('P0001');end if;
 if exists(select 1 from private.company_registry_execution_windows where operation_id=p_operation and claimed_at is null)then if private.claim_registry_execution_window(p_operation,actor,sid,p_request)is null then perform private.hmac_model_fail('P0001');end if;end if;
 if not private.fence_registry_execution_window(p_operation,actor,sid,p_request)then perform private.hmac_model_fail('P0001');end if;
 perform pg_advisory_xact_lock(78103,hashtext(actor::text));
 select*into strict r from private.company_registrations z where z.requester_id=actor and z.request_id=p_request for update;
 snap:=private.company_registry_snapshot(actor,p_request);
 select*into o from private.company_registry_job_requests z where z.operation_id=p_operation;
 if found then
  if o.subject is distinct from actor or o.request_id is distinct from p_request or o.request_snapshot is distinct from snap or o.requester_session is distinct from sid then perform private.hmac_model_fail('P0001');end if;
  return private.company_registry_job_projection(p_request);
 end if;
 if r.state<>'pending'then return private.company_registry_job_projection(p_request);end if;
 if not exists(select 1 from private.company_controls c where c.company_id=r.company_id and c.state='pending'and c.cnpj is null and c.representation_state='unconfirmed')then perform private.hmac_model_fail('P0001');end if;
 select*into cfg from private.company_registry_sources z where not z.enabled and z.policy_version='company-legal-name-v2'and z.source='minhareceita-cnpj-v1'order by(z.source='minhareceita-cnpj-v1')desc limit 1 for share;
 if not found or exists(select 1 from private.company_controls c where c.cnpj=r.cnpj and c.company_id<>r.company_id)then return private.company_registry_job_projection(p_request);end if;
 select*into j from private.company_registry_jobs z where z.subject=actor and z.request_id=p_request and z.request_snapshot=snap and z.requester_session=sid and(z.source,z.policy_version)=(cfg.source,cfg.policy_version)and z.state<>'retired'order by z.created_at desc limit 1 for update;
 if found and j.state='ready'and private.company_registry_job_projection(p_request)->>'state'<>'ready'then
  update private.company_registry_jobs set state='retired',updated_at=clock_timestamp()where job_id=j.job_id;j.job_id:=null;
 elsif found and j.state='checking'and j.lease_expires_at<=clock_timestamp()and j.attempts>=3 then
  update private.company_registry_jobs set state='retired',updated_at=clock_timestamp()where job_id=j.job_id;j.job_id:=null;
 elsif found and j.state in('mismatch','not-found','unavailable')and j.retry_after<=clock_timestamp()then
  update private.company_registry_jobs set state='retired',updated_at=clock_timestamp()where job_id=j.job_id;j.job_id:=null;
 end if;
